    def try_start(self, limit: int | None = None) -> RunDecision:
        with self._lock:
            st = self.state()
            if not st["allowed"]:
                code = 409 if st["code"] == "busy" else 429
                return RunDecision(False, code, st["reason"], st["retry_after"], st["code"])
            if not self.pipeline.start_background("manual", limit):
