for f in ["app/youtube.py", "app/pipeline.py", "app/db.py", "app/main.py", "app/summarize.py", "tests/test_youtube.py", "tests/test_pipeline.py", "tests/test_web.py", "tests/test_db.py", "tests/conftest.py"]:
    src = Path(f).read_text()
    tree = ast.parse(src)
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) or isinstance(node, ast.Import):
            for a in node.names:
                imported[(a.asname or a.name).split(".")[0]] = node.lineno
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    unused = [k for k in imported if k not in names and k not in src.split("__all__")[-1][:0]]
    # crude: check textual usage count
    unused = [k for k in imported if src.count(k) <= 1]
    defs = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef,)) and not n.name.startswith("test_")]
    print(f, "unused imports:", unused)
EOF
grep -rn "title_tokens(" app tests

