cd ~/dev/skytec-metacritic && .venv/bin/python - <<'EOF'
import json, sqlite3, sys
from collections import Counter
sys.path.insert(0, ".")
from app.youtube import recheck_letsplay, trailer_problem, stored_candidate, parse_day
from app.pipeline import release_anchor
c = sqlite3.connect("data/games.db")
plat = {}
for gid, d in c.execute("select game_id, release_date from platforms"):
    plat.setdefault(gid, []).append(d)
st = Counter()
bad = []
for gid, title, rd, lp, tr, vurl in c.execute("select id, title, release_date, letsplay, trailer, video_embed_url from games"):
    a = release_anchor(rd, plat.get(gid, []))
    lp = json.loads(lp) if lp else {}
    tr = json.loads(tr) if tr else {}
    st["lp:" + str(lp.get("status")) + ":" + str(lp.get("method"))] += 1
    if lp.get("video"):
        r = recheck_letsplay(title, stored_candidate(lp["video"]), a, parse_day(lp.get("updated_at")))
        if r: bad.append(("lp", title, r))
        if lp.get("status") == "ok" and lp.get("about_this_game") is not True: bad.append(("lp-unverified", title, lp.get("method")))
    if tr.get("status") == "ok":
        r = trailer_problem(title, stored_candidate(tr["video"]), a, parse_day(tr.get("updated_at")), strict_edition=not tr["video"].get("base_game"))
        if r: bad.append(("tr", title, r))
    st["video:" + ("metacritic" if vurl else ("youtube" if tr.get("status") == "ok" else "none"))] += 1
    st["skipped_no_comment"] += sum(1 for s in lp.get("skipped") or [] if "оценок игры" in s.get("reason","") or "почти нет речи" in s.get("reason",""))
    st["skipped_llm_nocomment"] += sum(1 for s in lp.get("skipped") or [] if "оценок игры" in s.get("reason",""))
    st["rejected_entries"] += len(lp.get("rejected") or [])
    st["rejected_llm"] += sum(1 for r in lp.get("rejected") or [] if "LLM" in r.get("reason",""))
    st["games_with_rejected"] += 1 if lp.get("rejected") else 0
    st["passed_over_games"] += 1 if lp.get("passed_over") else 0
    st["transcript_" + str(lp.get("transcript_method"))] += 1 if lp.get("status") == "ok" else 0
for k, v in sorted(st.items()): print(k, v)
print("BAD", bad)
EOF

